var t=`0623-kamounia`;var n=`world-0623`;var a=`TN`;var s=`northern-africa`;var o=4;var r=46;var l={en:`Kamounia`,ua:`Камунія`};var g={en:`Kamounia is a Tunisia classic prepared with beef liver, yellow onion, garlic, tomato paste. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Камунія, страва кухні країни Туніс зі складниками: яловича печінка, жовта цибуля, часник, томатна паста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`beef-liver`,550,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`yellow-onion`,170,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,4,`clove`],[`tomato-paste`,45,`g`],[`ground-cumin`,8,`g`],[`sweet-paprika`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`beef-stock`,480,`ml`],[`tomato`,250,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`]]}];var m={slug:t,id:n,country:`TN`,region:s,servings:4,minutes:46,title:l,text:g,steps:u};export{a as country,m as default,n as id,r as minutes,s as region,o as servings,t as slug,u as steps,g as text,l as title};